export type YoutubeCaptionLine = {
  /** seconds */
  start: number;
  /** seconds */
  end: number;
  text: string;
};

export type YoutubeCaptions = {
  title: string;
  /** true when only YouTube's auto-generated (ASR) track was available */
  autoGenerated: boolean;
  lines: YoutubeCaptionLine[];
};
